import axios from 'axios';

export const getAllData = async () => {
  let data = {};
  try {
    data = await axios.get('https://memorabilia-1891b-default-rtdb.firebaseio.com/.json?auth=xgFGidHWDE2dwYeFiNdHanCbm2uGtXdTI0JDWgB7');
    
  } catch(e) {
    console.log('error fetching', e);
    throw 'Error ' + e; 
  }
  if (data && Object.keys(data)) {
    return data.data;
  }
};

export const getSearch = async (searchTerm) => {
  let data = {};
  try {
    data = await axios.get(`https://memorabilia-1891b-default-rtdb.firebaseio.com/.json?orderBy="*".equalTo="${searchTerm}"`);
    
  } catch(e) {
    console.log('error fetching', e);
    throw 'Error ' + e; 
  }
  if (data && Object.keys(data)) {
    return data.data;
  }
};

export const getCategory = async (category) => {
  let data = {};
  try {
    data = await axios.get(`https://memorabilia-1891b-default-rtdb.firebaseio.com/.json?orderBy="categories/${category}"&equalTo=true`);
    // console.log('data for category???', data)
  } catch(e) {
    console.log('error fetching', e);
    throw 'Error ' + e; 
  }
  if (data && Object.keys(data)) {
    return data.data;
  }
};

